function isDesignProblem(slug, topics = []) {
  const s6 = (slug ?? "").toLowerCase();
  const t9 = (topics ?? []).map((x3) => String(x3).toLowerCase()).join(" ");
  return /design-hashmap|design-hashset|lru-cache|lfu-cache|min-stack|design-circular-queue|design-circular-deque/.test(
    s6
  ) || /design/i.test(t9);
}
